use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var out = "";
    var i = 0;
    while i < signals.len() {
        if i > 0 {
            out = out.concat(other: ";");
        }
        let described = match signals.get(index: i) {
            Some(harbor.signal.Signal.Calm) => "calm",
            Some(harbor.signal.Signal.Gale(knots)) => "gale:".concat(other: knots.to_text()),
            Some(harbor.signal.Signal.Fog(density)) => "fog:".concat(other: density),
            None => "",
        };
        out = out.concat(other: described);
        i = i + 1;
    }
    out
}

use mill.stock;
use mill.rules;

fn lines() -> String {
    let inventory = stock.inventory();
    var text = "";
    var i = 0;
    while i < inventory.len() {
        let plank = inventory.get(i);
        if rules.keep(plank: plank) {
            let label = rules.label(plank: plank);
            if text == "" {
                text = label;
            } else {
                text = text.concat(other: ",").concat(other: label);
            }
        }
        i = i + 1;
    }
    text
}

